from flask import Flask, request
import subprocess
app = Flask(__name__)
@app.get('/lookup')
def lookup():
    host = request.args.get('host', 'localhost')
    return subprocess.check_output('nslookup ' + host, shell=True, text=True)

from flask import Flask, request, abort
import subprocess
app = Flask(__name__)
@app.get('/lookup')
def lookup():
    host = request.args.get('host', 'localhost')
    if host not in {'localhost', 'example.com'}:
        abort(400)
    return subprocess.check_output(['nslookup', host], shell=False, text=True)

