package main
import ("net/http"; "os/exec")
func main() {
 http.HandleFunc("/lookup", func(w http.ResponseWriter, r *http.Request) {
  host := r.URL.Query().Get("host")
  out, _ := exec.Command("sh", "-c", "nslookup " + host).Output()
  w.Write(out)
 })
 http.ListenAndServe(":8080", nil)
}

